#!/bin/sh
# Loads the parsed IMDB TSVs into a fresh `imdb_new` schema, then swaps it in
# for `imdb` in a single transaction. The previous data stays queryable until
# the swap, and a failed load leaves it untouched.
#
# Connection settings come from the standard PG* environment variables.

set -eu

PARSED_DIR="${PARSED_DIR:-/src/parsed}"
SQL_DIR="${SQL_DIR:-/loader/sql}"
KEEP_PARSED="${KEEP_PARSED:-false}"

# Unqualified names in types.sql (generated by the parser) resolve to imdb_new.
# client_min_messages hides the harmless "schema does not exist, skipping" notices.
export PGOPTIONS="-c search_path=imdb_new -c client_min_messages=warning"

run_psql() {
  psql -X -q -v ON_ERROR_STOP=1 "$@"
}

copy_table() {
  table="$1"
  file="$PARSED_DIR/$2.tsv"
  echo "Loading $file into $table..."
  # CSV format with a quote character that never appears in the data, so quotes are kept literally.
  run_psql -c "\\copy $table FROM '$file' WITH (FORMAT csv, DELIMITER E'\\t', HEADER false, QUOTE E'\\b', NULL '\\N')"
}

for name in types.sql title.basics.tsv title.episode.tsv name.basics.tsv title.principals.tsv title.ratings.tsv; do
  if [ ! -f "$PARSED_DIR/$name" ]; then
    echo "ERROR: $PARSED_DIR/$name is missing. Run the parser first (make parse)." >&2
    exit 1
  fi
done

echo "Creating schema imdb_new..."
run_psql -f "$SQL_DIR/01_prepare.sql"
run_psql -f "$PARSED_DIR/types.sql"
run_psql -f "$SQL_DIR/02_tables.sql"

copy_table imdb_new.title title.basics
copy_table imdb_new.episode title.episode
copy_table imdb_new.person name.basics
copy_table imdb_new.principal title.principals
copy_table imdb_new.rating title.ratings

echo "Removing orphaned rows..."
run_psql -f "$SQL_DIR/03_cleanup.sql"

echo "Adding constraints and indexes (this is the slow part)..."
run_psql -f "$SQL_DIR/04_constraints.sql"

echo "Granting privileges..."
run_psql -f "$SQL_DIR/05_grants.sql"

echo "Updating planner statistics..."
run_psql -c "VACUUM (ANALYZE) imdb_new.title, imdb_new.episode, imdb_new.person, imdb_new.principal, imdb_new.rating"

echo "Swapping imdb_new in as imdb..."
run_psql -f "$SQL_DIR/06_swap.sql"

if [ "$KEEP_PARSED" = "true" ]; then
  echo "KEEP_PARSED=true, leaving parsed files in $PARSED_DIR"
else
  echo "Removing parsed files from $PARSED_DIR (downloads are kept)..."
  rm -f "$PARSED_DIR"/*.tsv
fi

echo "Load complete."
